.option-item input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.option-label {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  user-select: none;
}

.option-label:hover {
  background: rgba(108, 99, 255, 0.08);
  border-color: var(--border-hover);
}

.option-item input[type="checkbox"]:checked + .option-label {
  background: var(--accent-check);
  border-color: var(--accent);
}

.option-item input[type="checkbox"]:focus-visible + .option-label {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.custom-checkbox {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border: 2px solid var(--border-hover);
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, border-color 0.15s;
  background: transparent;
}

.option-item input[type="checkbox"]:checked + .option-label .custom-checkbox {
  background: var(--accent);
  border-color: var(--accent);
}

.checkmark {
  display: none;
  width: 11px;
  height: 11px;
}

.option-item input[type="checkbox"]:checked + .option-label .checkmark {
  display: block;
}

.option-letter {
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.option-item input[type="checkbox"]:checked + .option-label .option-letter {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.option-text {
  font-size: 0.93rem;
  color: var(--text);
  font-weight: 500;
}

/* Submit area */
.quiz-footer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: stretch;
}

.submit-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 16px 32px;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  letter-spacing: 0.01em;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  box-shadow: 0 4px 24px rgba(108, 99, 255, 0.35);
}

.submit-btn:hover {
  background: var(--accent-hover);
  box-shadow: 0 6px 32px rgba(108, 99, 255, 0.5);
  transform: translateY(-1px);
}

.submit-btn:active {
  transform: translateY(0);
}

.submit-btn svg {
  width: 18px;
  height: 18px;
}

/* Result banner */
.result-banner {
  display: none;
  align-items: center;
  gap: 12px;
  background: var(--success-dim);
  border: 1px solid rgba(76, 175, 125, 0.35);
  border-radius: var(--radius);
  padding: 16px 20px;
  color: var(--success);
  font-size: 0.95rem;
  font-weight: 600;
}

.result-banner.show {
  display: flex;
}

.result-banner svg {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
}

.result-score {
  font-size: 1.5rem;
  font-weight: 800;
  margin-left: auto;
  color: var(--success);
}

/* Correct/incorrect feedback */
.option-item.correct input[type="checkbox"]:checked + .option-label {
  background: var(--success-dim);
  border-color: var(--success);
}

.option-item.correct input[type="checkbox"]:checked + .option-label .custom-checkbox {
  background: var(--success);
  border-color: var(--success);
}

.option-item.incorrect input[type="checkbox"]:checked + .option-label {
  background: rgba(255, 107, 138, 0.15);
  border-color: #ff6b8a;
}

.option-item.incorrect input[type="checkbox"]:checked + .option-label .custom-checkbox {
  background: #ff6b8a;
  border-color: #ff6b8a;
}

.option-item.missed + .option-label,
.option-item.missed > .option-label {
  border-color: var(--success);
  background: rgba(76, 175, 125, 0.05);
}

.feedback-tag {
  margin-left: auto;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 100px;
  display: none;
}

.option-item.correct .feedback-tag,
.option-item.incorrect .feedback-tag,
.option-item.missed .feedback-tag {
  display: block;
}

.option-item.correct .feedback-tag {
  background: rgba(76, 175, 125, 0.2);
  color: var(--success);
}

.option-item.incorrect .feedback-tag {
  background: rgba(255, 107, 138, 0.2);
  color: #ff6b8a;
}

.option-item.missed .feedback-tag {
  background: rgba(76, 175, 125, 0.12);
  color: var(--success);
}

.progress-bar-wrap {
  height: 4px;
  background: var(--surface-2);
  border-radius: 2px;
  overflow: hidden;
  margin-bottom: 8px;
}

.progress-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), #a78bfa);
  border-radius: 2px;
  transition: width 0.4s ease;
  width: 0%;
}

.progress-label {
  font-size: 12px;
  color: var(--text-dim);
  text-align: right;
  margin-bottom: 32px;
}
