function CheckmarkSVG() {
  return `<svg class="checkmark" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg">
    <polyline points="1.5,6 4.5,9.5 10.5,2.5" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function renderOption(opt, questionId) {
  return `
    <li class="option-item" data-value="${opt.value}">
      <input type="checkbox" id="${questionId}-${opt.value}" name="${questionId}" value="${opt.value}">
      <label class="option-label" for="${questionId}-${opt.value}">
        <span class="custom-checkbox">${CheckmarkSVG()}</span>
        <span class="option-letter">${opt.letter}</span>
        <span class="option-text">${opt.label}</span>
        <span class="feedback-tag"></span>
      </label>
    </li>`;
}

function renderQuestion(q) {
  const helpBlock = q.helpText
    ? `<div class="help-text">
        <span class="help-icon">i</span>
        <span>${q.helpText}</span>
       </div>`
    : "";

  return `
    <div class="form-field" id="field-${q.id}">
      <div class="question-meta">
        <span class="question-number">${q.number}</span>
        <span class="question-required">Select all that apply</span>
      </div>
      <p class="question-text">${q.text}</p>
      ${helpBlock}
      <ul class="options-list">
        ${q.options.map(opt => renderOption(opt, q.id)).join("")}
      </ul>
    </div>`;
}

function renderProgressBar() {
  return `
    <div class="progress-bar-wrap"><div class="progress-bar" id="progress-bar"></div></div>
    <p class="progress-label" id="progress-label">0 of ${QUIZ_DATA.length} answered</p>`;
}

function renderSubmitBtn() {
  return `
    <button type="button" class="submit-btn" id="submit-btn">
      <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M9 12l2 2 4-4M21 12a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
      Submit Quiz
    </button>
    <div class="result-banner" id="result-banner">
      <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M9 12l2 2 4-4M21 12a9 9 0 11-18 0 9 9 0 0118 0z" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
      <span id="result-message"></span>
      <span class="result-score" id="result-score"></span>
    </div>`;
}

function mount() {
  const app = document.getElementById("quiz-app");

  app.innerHTML = `
    <div class="quiz-header">
      <div class="quiz-badge">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="2"/><path d="M12 8v4l3 3" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
        3 Questions
      </div>
      <h1>Computer Languages Quiz</h1>
      <p>Test your knowledge of programming language concepts.<br>Each question may have more than one correct answer.</p>
    </div>
    <form class="quiz-form" id="quiz-form" novalidate>
      ${renderProgressBar()}
      ${QUIZ_DATA.map(renderQuestion).join("")}
      <div class="quiz-footer">
        ${renderSubmitBtn()}
      </div>
    </form>`;

  attachListeners();
}

function attachListeners() {
  const checkboxes = document.querySelectorAll('input[type="checkbox"]');
  checkboxes.forEach(cb => cb.addEventListener("change", updateProgress));
  document.getElementById("submit-btn").addEventListener("click", handleSubmit);
}

function updateProgress() {
  const answered = QUIZ_DATA.filter(q => {
    return document.querySelectorAll(`input[name="${q.id}"]:checked`).length > 0;
  }).length;

  const pct = (answered / QUIZ_DATA.length) * 100;
  document.getElementById("progress-bar").style.width = pct + "%";
  document.getElementById("progress-label").textContent =
    `${answered} of ${QUIZ_DATA.length} answered`;
}

function handleSubmit() {
  let totalCorrect = 0;

  QUIZ_DATA.forEach(q => {
    const selected = Array.from(
      document.querySelectorAll(`input[name="${q.id}"]:checked`)
    ).map(cb => cb.value);

    const correct = q.correct;
    const allOptions = document.querySelectorAll(`#field-${q.id} .option-item`);

    allOptions.forEach(item => {
      item.classList.remove("correct", "incorrect", "missed");
      const tag = item.querySelector(".feedback-tag");
      tag.textContent = "";

      const val = item.dataset.value;
      const isSelected = selected.includes(val);
      const isCorrect = correct.includes(val);

      if (isSelected && isCorrect) {
        item.classList.add("correct");
        tag.textContent = "✓ Correct";
      } else if (isSelected && !isCorrect) {
        item.classList.add("incorrect");
        tag.textContent = "✗ Wrong";
      } else if (!isSelected && isCorrect) {
        item.classList.add("missed");
        tag.textContent = "Missed";
      }
    });

    const isQuestionCorrect =
      selected.length === correct.length &&
      selected.every(v => correct.includes(v));

    if (isQuestionCorrect) totalCorrect++;
  });

  const banner = document.getElementById("result-banner");
  const message = document.getElementById("result-message");
  const score = document.getElementById("result-score");

  const pct = Math.round((totalCorrect / QUIZ_DATA.length) * 100);
  let msg = "Great effort! Review the answers above.";
  if (pct === 100) msg = "Perfect score! You nailed it! 🎉";
  else if (pct >= 67) msg = "Nice work! Almost there.";

  message.textContent = msg;
  score.textContent = `${totalCorrect} / ${QUIZ_DATA.length}`;
  banner.classList.add("show");

  document.getElementById("submit-btn").textContent = "Resubmit";
  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

document.addEventListener("DOMContentLoaded", mount);
